import {registerCardComponent} from "@pihanga2/core";

import {Component} from "./stack.component";
import {STACK_CARD} from "./stack.types";

export * from "./stack.types";

registerCardComponent({
  name: STACK_CARD,
  component: Component,
});

import * as React from "react";
import type {StackProps} from "./stack.types";

import {Card, type PiCardProps} from "@pihanga2/core";
import clsx from "clsx";
import {Fragment} from "react";

export type SelectSD = {
  root?: string;
};

export const Component = (props: PiCardProps<StackProps>): React.ReactNode => {
  const {
    content,
    direction,
    divider,
    spacing,
    justifyContent,
    alignItems,
    className,
    style,
    cardName,
  } = props;
  const sd: SelectSD = (style as {shad?: SelectSD} | undefined)?.shad || {};

  const cn = [className, sd.root, "flex"];
  if (direction) {
    switch (direction) {
      // "column-reverse" | "column" | "row-reverse" | "row"
      case "row":
        cn.push("flex-row");
        break;
      case "row-reverse":
        cn.push("flex-row-reverse");
        break;
      case "column":
        cn.push("flex-col");
        break;
      case "column-reverse":
        cn.push("flex-col-reverse");
        break;
    }
  }
  if (justifyContent) {
    switch (justifyContent) {
      // "flex-start" | "center" | "flex-end" | "space-between" | "space-around" | "space-evenly"
      case "flex-start":
        cn.push("justify-start");
        break;
      case "center":
        cn.push("justify-center");
        break;
      case "flex-end":
        cn.push("justify-end");
        break;
      case "space-between":
        cn.push("justify-between");
        break;
      case "space-around":
        cn.push("justify-around");
        break;
      case "space-evenly":
        cn.push("justify-evenly");
        break;
    }
  }
  if (alignItems) {
    switch (alignItems) {
      // "flex-start" | "center" | "flex-end" | "normal" | "stretch" | "start" | "end" | "baseline" | "initial" | "inherit"
      case "flex-start":
        cn.push("items-start");
        break;
      case "center":
        cn.push("items-center");
        break;
      case "stretch":
        cn.push("items-stretch");
        break;
      case "flex-end":
        cn.push("items-end");
        break;
      case "baseline":
        cn.push("items-baseline");
        break;
      default:
        console.warn("stack: unsupported 'alignItems' property", alignItems);
    }
  }
  if (spacing && spacing > 0) {
    if (
      direction === undefined ||
      direction === "row" ||
      direction === "row-reverse"
    ) {
      cn.push(`gap-${spacing}`);
    } else {
      cn.push(`gap-${spacing}`);
    }
  }

  // const sx = style?.joy
  // const p = {
  //   direction,
  //   spacing,
  //   justifyContent,
  //   alignItems,
  //   divider: divider ? <Card cardName={divider} parentCard={cardName} /> : null,
  //   sx,
  //   className,
  // }

  function renderContent() {
    if (!content) return null;

    return content.map((cn, i) => (
      <Fragment key={i}>
        <Card cardName={cn} parentCard={cardName} key={`item-${i}`} />
        {divider && i < content.length - 1 && (
          <Card cardName={divider} parentCard={cardName} key={`divider-${i}`} />
        )}
      </Fragment>
    ));
  }

  return (
    <div className={clsx(cn)} data-pihanga={cardName}>
      {renderContent()}
      {props.children}
    </div>
  );
};

import {type PiCardRef, createCardDeclaration} from "@pihanga2/core";

export const STACK_CARD = "shad/stack";

/**
 * CSS `flex-direction` values supported by the Stack card.
 */
export type DirectionT = "column-reverse" | "column" | "row-reverse" | "row";

/**
 * CSS `justify-content` values supported by the Stack card.
 */
export type JustifyContentT =
  | "flex-start"
  | "center"
  | "flex-end"
  | "space-between"
  | "space-around"
  | "space-evenly";

/**
 * CSS `align-items` values supported by the Stack card.
 */
export type AlignItemsT =
  | "normal"
  | "stretch"
  | "center"
  | "flex-start"
  | "flex-end"
  | "start"
  | "end"
  | "baseline"
  | "initial"
  | "inherit";

export type StackProps<S = object> = {
  /** Ordered list of child card refs to render */
  content: PiCardRef[];

  /** Flex direction — defaults to `"column"` */
  direction?: DirectionT;
  /** Optional card ref rendered as a separator between children */
  divider?: PiCardRef;
  /** Tailwind gap spacing units between children */
  spacing?: number;

  justifyContent?: JustifyContentT;
  alignItems?: AlignItemsT;

  /** Additional Tailwind utility classes */
  className?: string;
  /** Card style object (use the `shad` key for Tailwind-compatible overrides) */
  style?: S;
};

/**
 * Factory function for declaring a `shad/stack` card instance.
 *
 * ```ts
 * import {registerCard} from "@pihanga2/core";
 * import {Stack} from "@/cards/stack";
 *
 * registerCard("myApp/toolbar", Stack({
 *   direction:      "row",
 *   spacing:        2,
 *   alignItems:     "center",
 *   justifyContent: "space-between",
 *   content:        ["myApp/logo", "myApp/navLinks", "myApp/userMenu"],
 * }));
 * ```
 */
export const Stack = createCardDeclaration<StackProps>(STACK_CARD);
